export function worldToLatLon(x, z) {
  return {
    lat: Number((41.3102 - z / 23726).toFixed(6)),
    lon: Number((69.278 + x / 17795).toFixed(6)),
  };
}

export function latLonToWorld(lat, lon) {
  return {
    x: Math.round((lon - 69.278) * 17795),
    z: Math.round((41.3102 - lat) * 23726),
  };
}

